var lengthOfLongestSubsequence = function(nums, target) {
    const dp = new Int32Array(target + 1).fill(-1);
    dp[0] = 0;
    for (const x of nums) {
        for (let t = target; t >= x; t--) {
            if (dp[t - x] !== -1) {
                if (dp[t - x] + 1 > dp[t]) dp[t] = dp[t - x] + 1;
            }
        }
    }
    return dp[target];
};
